update translations t set voice_advice = case t.locale when 'en' then 'Heavy rain is close. Protect harvested grain and open drainage in your field.' else 'ከባድ ዝናብ ቅርብ ነው። የታጨደ እህልዎን ይሸፍኑ፣ የማሳዎትንም ውሃ መውረጃ ይክፈቱ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Ants carrying eggs uphill' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The birds'' feathers are greyish, so poor rain is expected this season. Choose drought-tolerant seed and save soil moisture.' else 'የወፎቹ ላባ ግራጫማ ስለሆነ በዚህ ወቅት ደካማ ዝናብ ይጠበቃል። ድርቅን የሚቋቋም ዘር ይምረጡ፤ የአፈሩንም እርጥበት ይጠብቁ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Bird plumage colouration' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The wind is showing a change of season. Get your land ready, and choose your sowing day when the rains begin.' else 'ንፋሱ የወቅት ለውጥ እያሳየ ነው። መሬትዎን ያዘጋጁ፤ የሚዘሩበትን ቀን ደግሞ ዝናቡ ሲጀምር ይወስኑ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Wind pattern changes' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The stars point to how the coming season will be. Plan your seed and sowing for the season ahead, and watch other signs too.' else 'ከዋክብቱ የሚመጣው ወቅት ምን እንደሚመስል ያመለክታሉ። ለሚመጣው ወቅት ዘርዎንና የመዝሪያ ጊዜዎን ያቅዱ፤ ሌሎች ምልክቶችንም ይከታተሉ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Star pattern shifts' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Rain may be on the way. Keep harvested crops covered, and do not spread fertilizer just before rain.' else 'ዝናብ ሊመጣ ይችላል። የታጨደ ሰብልዎን ሸፍነው ያቆዩ፤ ከዝናብ በፊት ማዳበሪያ አይበትኑ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Coloured solar or lunar rings' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Mist and fog in the rainy season can bring rain. Prepare your field and keep your seed ready.' else 'በዝናብ ወቅት የሚታይ ጉምና ጭጋግ ዝናብ ሊያመጣ ይችላል። ማሳዎን ያዘጋጁ፤ ዘርዎንም ዝግጁ ያድርጉ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Misty and foggy conditions' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Normal rain is expected. Follow your usual sowing plan.' else 'መደበኛ ዝናብ ይጠበቃል። የተለመደውን የመዝሪያ ዕቅድዎን ይከተሉ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Ants marching in line' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The stars and the moon point to how the season will be. Plan your seed and sowing for the season ahead.' else 'ከዋክብቱና ጨረቃዋ ወቅቱ ምን እንደሚመስል ያመለክታሉ። ለሚመጣው ወቅት ዘርዎንና የመዝሪያ ጊዜዎን ያቅዱ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Star–moon alignment' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'A normal rainy season is expected. Prepare your land and seed as usual.' else 'መደበኛ የዝናብ ወቅት ይጠበቃል። እንደተለመደው መሬትዎንና ዘርዎን ያዘጋጁ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Squirrel digging behaviour' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Dry times may be coming. Save soil moisture, choose drought-tolerant seed, and store feed and water.' else 'ደረቅ ጊዜ ሊመጣ ይችላል። የአፈሩን እርጥበት ይጠብቁ፣ ድርቅን የሚቋቋም ዘር ይምረጡ፣ መኖና ውሃም ያከማቹ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Dispersed ant behaviour' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The rains should start at the usual time. Get your land ready to sow.' else 'ዝናቡ በተለመደው ጊዜ ይጀምራል። ለመዝራት መሬትዎን ያዘጋጁ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Dusty slow winds' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Dry times may be coming. Wait to sow until the soil is moist, and save water and soil moisture.' else 'ደረቅ ጊዜ ሊመጣ ይችላል። አፈሩ እስኪረጥብ ድረስ መዝራትን ያዘግዩ፤ ውሃንና የአፈርን እርጥበት ይቆጥቡ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Strong east-to-west winds' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Normal rain is expected. Carry on with your usual farm plan.' else 'መደበኛ ዝናብ ይጠበቃል። የተለመደውን የእርሻ ዕቅድዎን ይቀጥሉ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Red sun at sunrise' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'The trees show that the season is changing. Start preparing your land and plan your planting.' else 'ዛፎቹ ወቅቱ እየተለወጠ መሆኑን ያሳያሉ። መሬትዎን ማዘጋጀት ይጀምሩ፤ የሚተክሉበትንም ጊዜ ያቅዱ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Flowering of trees' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Rain is coming this season. Prepare your field and seed.' else 'በዚህ ወቅት ዝናብ ይመጣል። ማሳዎንና ዘርዎን ያዘጋጁ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Frogs croaking' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Rains are on the way. Start preparing the land now.' else 'ዝናብ እየመጣ ነው። መሬትዎን አሁን ማዘጋጀት ይጀምሩ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Birds migrating from far away' and t.locale in ('en','am');
update translations t set voice_advice = case t.locale when 'en' then 'Rain is coming within hours or days. Cover harvested crops, and get ready to sow after a good rain.' else 'በጥቂት ሰዓታት ወይም ቀናት ውስጥ ዝናብ ይመጣል። የታጨደ ሰብልዎን ይሸፍኑ፤ ጥሩ ዝናብ ከዘነበ በኋላ ለመዝራት ይዘጋጁ።' end from translations e where e.record_id = t.record_id and e.locale = 'en' and e.name = 'Dark cloud formation and movement' and t.locale in ('en','am');
-- All field scores were recorded in Wolaita.
update sign_evaluations s set location_id = (select id from locations where slug = 'wol'),
  observation_date = coalesce(s.observation_date, k.observation_date), method_version = coalesce(s.method_version, 'field-ai-2025')
from knowledge_records k where k.id = s.record_id and s.location_id is null and s.tested_with = 'Sign & Sky platform';
commit;
